int main(){@autoreleasepool{auto d=MTLCreateSystemDefaultDevice();if(!d)return 2;std::string k=Garnet::kDenseDecode512Shader;auto p=k.find("specialized_bf16_decode_dense512");k.replace(p,std::string("specialized_bf16_decode_dense512").size(),"specialized_bf16_decode_dense1024");p=k.find("ulong(group)*64+simd*4");k.replace(p,std::string("ulong(group)*64+simd*4").size(),"ulong(group)*128+simd*4");std::string source="#include <metal_stdlib>\nusing namespace metal;\nstruct BF16Params {ulong rows,inner,columns,aStride,oStride;};\n";source+=Garnet::kBodyShapeShader;source+=k;NSError* e=nil;auto options=[MTLCompileOptions new];options.fastMathEnabled=YES;auto lib=[d newLibraryWithSource:[NSString stringWithUTF8String:source.c_str()] options:options error:&e];if(!lib){fprintf(stderr,"%s\n",e.description.UTF8String);return 3;}bool feasible=true;for(uint inner:{2048u,6144u})for(uint columns:{272u,1024u,2048u,6144u}){uint v[5]={1,inner,columns,inner,columns};auto c=[MTLFunctionConstantValues new];for(NSUInteger i=0;i<5;i++)[c setConstantValue:&v[i] type:MTLDataTypeUInt atIndex:i];bool tail=columns%128==0;[c setConstantValue:&tail type:MTLDataTypeBool atIndex:5];auto f=[lib newFunctionWithName:@"specialized_bf16_decode_dense1024" constantValues:c error:&e];auto pipeline=f?[d newComputePipelineStateWithFunction:f error:&e]:nil;if(!pipeline){fprintf(stderr,"%s\n",e.description.UTF8String);return 4;}bool ok=pipeline.threadExecutionWidth==32&&pipeline.maxTotalThreadsPerThreadgroup>=1024;feasible&=ok;printf("{\"inner\":%u,\"columns\":%u,\"simd_width\":%lu,\"pipeline_max_threads\":%lu,\"feasible\":%s}\n",inner,columns,(unsigned long)pipeline.threadExecutionWidth,(unsigned long)pipeline.maxTotalThreadsPerThreadgroup,ok?"true":"false");}return feasible?0:5;}}
